// SPDX-License-Identifier: MIT

pragma solidity ^0.8.13;

contract Function {
    // functions can return multiple values

    function returnMany() public pure    returns (
        uint, bool, uint
    ) {
        return (1, true, 2);
    }

    // Return values by name
    function named() public pure returns (uint x, bool b, uint y) {
        return (4, false, 29);
    }

    // Return values can be assigned to their name
    // In this case, the return statement can be omitted.
    function assigned() public pure returns (uint x, bool b, uint y) {
        x = 19;
        b = true;
        y = 30;
    }

    // Use destructuring assignment when calling another
    // function that returns multiple values
    function destructuringAssignments() public pure returns(uint, bool, uint, uint) {
        (uint i, bool b, uint j) = returnMany();   

        // values can be left out. 
        (uint x, , uint y) = (4, 5, 6);

        return (i, b, j, x + y);
    }

    // Cannot use map for either input or output
    // Can use array for input
    function arrayInput(uint[] memory _arr) public pure {}

    // Can use array for output
    function arrayOutput(uint[] memory _arr) public pure returns(uint[] memory) {
        return _arr;    
    }

}

contract XYZ {
    function someFuncWithManyInputs(
        uint x,
        uint y,
        uint z,
        address a,
        bool b,
        string memory c
    ) public pure returns (uint) {

    }

    function callFunc() external pure returns (uint) {
        return someFuncWithManyInputs(1, 2, 3, address(0), true, "web 3.0");
    }

    function callFuncWithKeyValue() external pure returns (uint) {
        return someFuncWithManyInputs({
            a: address(0),
            b: true,
            c: "Key value pairs",
            x: 1,
            y: 2,
            z: 190
        }); 
    }
}

